/* ---------------- 미로 탈출 챌린지 (혼자하기 + 온라인 둘 다 가능) ---------------- */
/* 시작 전 캐릭터를 고르고, 방향키(화살표)로 미로를 움직여서 깃발까지 가면 클리어입니다.
   미로는 할 때마다 새로 랜덤 생성되고(레벨이 오를수록 살짝 커짐), 3개를 모두 통과하면 성공.
   온라인일 때는 각자 자기 미로를 풀고, 총 걸린 시간으로 방 친구들과 순위를 비교합니다
   (실시간으로 같은 화면을 공유하는 게 아니라, 10초 감각 게임처럼 "각자 도전 후 기록 비교" 방식). */
var MZ_CHARACTERS = [
  { id: 'kkanni', img: 'data:image/png;base64,', name: '깐니' },
  { id: 'ssuyeong', img: 'data:image/png;base64,', name: '쑤영' },
  { id: 'jeonni', img: 'data:image/png;base64,', name: '젼니' }
];
/* 미로가 너무 쉽다는 의견이 있어서 두 가지를 바꿨습니다:
   1) 미로 크기를 조금 더 키움 (7/9/11 -> 9/11/13)
   2) "안개(fog)" 효과 추가 - 예전엔 미로 전체가 처음부터 다 보여서 눈으로 길을 미리 찾을 수
      있었는데, 이제는 캐릭터 주변(한 칸)만 보이고 나머지는 어두운 안개로 가려져 있어서
      실제로 이동하면서 길을 기억하고 탐험해야 합니다. 한 번 밝혀진 칸은 계속 보입니다.
   그래도 너무 쉽다는 의견이 다시 있어서(시야를 더 가리는 방식 말고, 미로 자체의 난이도를
   올려달라는 요청) 이번엔 두 가지를 더 바꿨습니다:
   3) 미로 크기를 한 번 더 키움 (9/11/13 -> 13/17/21)
   4) 미로를 만드는 방식(랜덤 DFS)에 "방향 편향"을 추가 - 예전엔 매번 다음 칸을 완전히
      무작위로 골라서 통로가 자주 꺾이고 비교적 짧게 갈라졌는데, 이제는 직전에 오던 방향을
      더 자주 우선해서 길게 이어지는 구불구불한 통로가 만들어집니다. 길이 훨씬 길고 헷갈리게
      이어지기 때문에, 화면에 다 보여도(안개 없이도) 실제로 훨씬 어려워집니다. */
var MZ_MAZE_SIZES = [13, 17, 21];
var MZ_TOTAL_ROUNDS = MZ_MAZE_SIZES.length;
var MZ_VISION_RADIUS = 1;
var MZ_REVEALED = null; // boolean[] - MZ_MAZE.cells와 같은 순서, 한 번 밝혀지면 계속 true

var MZ_SELECTED_CHAR = null;
var MZ_ROUND_IDX = 0;
var MZ_MAZE = null; // { size, cells: [{top,right,bottom,left}] }
var MZ_PLAYER = { x: 0, y: 0 };
var MZ_GOAL = { x: 0, y: 0 };
var MZ_ROUND_START_TIME = 0;
var MZ_ROUND_TIMES = [];
var MZ_TIMER_RAF = null;
var MZ_KEY_HANDLER = null;
var MZ_BEST_TOTAL = null;
var MZ_OPP_POLL_TIMER = null;
var MZ_INPUT_LOCKED = false;

function mzLoadBest() {
  try {
    var v = parseFloat(localStorage.getItem('gamehub_mz_best_total') || '');
    MZ_BEST_TOTAL = isNaN(v) ? null : v;
  } catch (e) { MZ_BEST_TOTAL = null; }
}
function mzSaveBest(total) {
  try { localStorage.setItem('gamehub_mz_best_total', String(total)); } catch (e) {}
}
function mzBestText() {
  return MZ_BEST_TOTAL !== null ? (MZ_BEST_TOTAL.toFixed(1) + '초') : '기록 없음';
}

function mzShowOnly(id) {
  ['mz-select-area', 'mz-round-area', 'mz-clear-area', 'mz-final-area'].forEach(function (elId) {
    document.getElementById(elId).style.display = (elId === id) ? '' : 'none';
  });
}

function startMaze() {
  mzLoadBest();
  document.getElementById('mz-best-intro').textContent = mzBestText();
  mzRenderCharPicker();
  mzShowOnly('mz-select-area');
  mzStopTimerLoop();
  mzDetachKeys();
  MZ_SELECTED_CHAR = null;
  mzStartOppPoll();
}

function mzRenderCharPicker() {
  var grid = document.getElementById('mz-char-grid');
  grid.innerHTML = MZ_CHARACTERS.map(function (c) {
    return '<button class="mz-char-btn" onclick="mzPickCharacter(\'' + c.id + '\')">' +
      '<span class="mz-char-emoji"><img src="' + c.img + '" alt="' + c.name + '" style="width:56px;height:72px;object-fit:cover;border-radius:10px;display:block;"></span>' +
      '<span class="mz-char-name">' + c.name + '</span></button>';
  }).join('');
}

function mzPickCharacter(charId) {
  MZ_SELECTED_CHAR = MZ_CHARACTERS.find(function (c) { return c.id === charId; }) || MZ_CHARACTERS[0];
  mzRestart();
}

function mzRestart() {
  if (!MZ_SELECTED_CHAR) MZ_SELECTED_CHAR = MZ_CHARACTERS[0];
  MZ_ROUND_IDX = 0;
  MZ_ROUND_TIMES = [];
  mzBeginRound();
}

function mzNextMaze() {
  MZ_ROUND_IDX++;
  if (MZ_ROUND_IDX >= MZ_TOTAL_ROUNDS) {
    mzShowFinal();
  } else {
    mzBeginRound();
  }
}

/* ---- 미로 생성 (랜덤 DFS 백트래커 + 방향 편향) ---- */
function mzGenerateMaze(size) {
  var cells = [];
  for (var y = 0; y < size; y++) {
    for (var x = 0; x < size; x++) {
      cells.push({ x: x, y: y, top: true, right: true, bottom: true, left: true, visited: false });
    }
  }
  function idx(x, y) { return y * size + x; }
  var stack = [];
  var dirStack = []; // 각 단계에서 "직전에 온 방향"을 같이 기록(백트래킹 때도 정확히 복원되도록)
  var start = cells[idx(0, 0)];
  start.visited = true;
  stack.push(start);
  dirStack.push(null);
  var opposite = { top: 'bottom', right: 'left', bottom: 'top', left: 'right' };
  while (stack.length) {
    var cur = stack[stack.length - 1];
    var lastDir = dirStack[dirStack.length - 1];
    var neighbors = [];
    if (cur.y > 0 && !cells[idx(cur.x, cur.y - 1)].visited) neighbors.push({ dir: 'top', cell: cells[idx(cur.x, cur.y - 1)] });
    if (cur.x < size - 1 && !cells[idx(cur.x + 1, cur.y)].visited) neighbors.push({ dir: 'right', cell: cells[idx(cur.x + 1, cur.y)] });
    if (cur.y < size - 1 && !cells[idx(cur.x, cur.y + 1)].visited) neighbors.push({ dir: 'bottom', cell: cells[idx(cur.x, cur.y + 1)] });
    if (cur.x > 0 && !cells[idx(cur.x - 1, cur.y)].visited) neighbors.push({ dir: 'left', cell: cells[idx(cur.x - 1, cur.y)] });
    if (!neighbors.length) { stack.pop(); dirStack.pop(); continue; }
    /* 직전에 오던 방향과 같은 후보가 있으면 뽑기 확률을 크게 높여서(가중치 4배), 통로가
       자주 꺾이지 않고 길게 이어지도록 합니다 - 그래야 잘못된 길로 한참 가서야 막다른
       곳인 걸 알게 되는, 더 헷갈리고 어려운 미로가 만들어집니다. */
    var pool = neighbors.slice();
    if (lastDir) {
      neighbors.forEach(function (n) { if (n.dir === lastDir) { pool.push(n); pool.push(n); pool.push(n); } });
    }
    var pick = pool[Math.floor(Math.random() * pool.length)];
    cur[pick.dir] = false;
    pick.cell[opposite[pick.dir]] = false;
    pick.cell.visited = true;
    stack.push(pick.cell);
    dirStack.push(pick.dir);
  }
  return { size: size, cells: cells };
}

function mzCellAt(x, y) { return MZ_MAZE.cells[y * MZ_MAZE.size + x]; }

function mzBeginRound() {
  mzShowOnly('mz-round-area');
  mzDetachKeys();
  var size = MZ_MAZE_SIZES[MZ_ROUND_IDX];
  MZ_MAZE = mzGenerateMaze(size);
  MZ_PLAYER = { x: 0, y: 0 };
  MZ_GOAL = { x: size - 1, y: size - 1 };
  MZ_REVEALED = new Array(size * size).fill(false);
  mzRevealAround(MZ_PLAYER.x, MZ_PLAYER.y);
  document.getElementById('mz-round-indicator').textContent = (MZ_ROUND_IDX + 1) + ' / ' + MZ_TOTAL_ROUNDS + ' 미로';
  mzRenderBoard();
  MZ_ROUND_START_TIME = performance.now();
  MZ_INPUT_LOCKED = false;
  mzStartTimerLoop();
  mzAttachKeys();
}

/* (x,y) 중심으로 MZ_VISION_RADIUS 칸 안쪽을 모두 "밝혀진" 상태로 표시합니다.
   한 번 밝혀진 칸은 이후 계속 보입니다(탐험한 지역을 기억하는 방식). */
function mzRevealAround(cx, cy) {
  var size = MZ_MAZE.size;
  for (var dy = -MZ_VISION_RADIUS; dy <= MZ_VISION_RADIUS; dy++) {
    for (var dx = -MZ_VISION_RADIUS; dx <= MZ_VISION_RADIUS; dx++) {
      var nx = cx + dx, ny = cy + dy;
      if (nx < 0 || ny < 0 || nx >= size || ny >= size) continue;
      MZ_REVEALED[ny * size + nx] = true;
    }
  }
}

function mzRenderBoard() {
  var board = document.getElementById('mz-board');
  var size = MZ_MAZE.size;
  board.style.gridTemplateColumns = 'repeat(' + size + ', 1fr)';
  /* 행(row) 크기도 열과 똑같이 1fr씩 고정해줘야, 칸 안에 캐릭터 이미지가 들어갔을 때
     그 이미지의 원본 크기 때문에 해당 줄만 커져서 미로 판이 움직일 때마다 울퉁불퉁
     벌어지는 문제가 생기지 않습니다(이미지가 없을 때도 항상 정사각형 칸을 유지). */
  board.style.gridTemplateRows = 'repeat(' + size + ', 1fr)';
  var html = MZ_MAZE.cells.map(function (cell, idx) {
    /* 안개(fog): 아직 밝혀지지 않은 칸은 벽이나 목표 표시 없이 그냥 어두운 칸으로만 보여줘서,
       미로 전체를 미리 훑어보고 길을 찾을 수 없게 합니다. */
    if (!MZ_REVEALED[idx]) {
      return '<div class="mz-cell mz-cell-fog"></div>';
    }
    var classes = ['mz-cell'];
    if (cell.top) classes.push('mz-wall-top');
    if (cell.right) classes.push('mz-wall-right');
    if (cell.bottom) classes.push('mz-wall-bottom');
    if (cell.left) classes.push('mz-wall-left');
    var content = '';
    if (cell.x === MZ_PLAYER.x && cell.y === MZ_PLAYER.y) { classes.push('mz-cell-player'); content = '<img src="' + MZ_SELECTED_CHAR.img + '" alt="' + MZ_SELECTED_CHAR.name + '" style="width:78%;height:78%;object-fit:contain;border-radius:6px;display:block;">'; }
    else if (cell.x === MZ_GOAL.x && cell.y === MZ_GOAL.y) { classes.push('mz-cell-goal'); content = '🚩'; }
    return '<div class="' + classes.join(' ') + '">' + content + '</div>';
  }).join('');
  board.innerHTML = html;
}

function mzStartTimerLoop() {
  mzStopTimerLoop();
  function tick() {
    var elapsed = (performance.now() - MZ_ROUND_START_TIME) / 1000;
    var timerEl = document.getElementById('mz-timer');
    if (timerEl) timerEl.textContent = elapsed.toFixed(1) + '초';
    MZ_TIMER_RAF = requestAnimationFrame(tick);
  }
  MZ_TIMER_RAF = requestAnimationFrame(tick);
}
function mzStopTimerLoop() {
  if (MZ_TIMER_RAF) cancelAnimationFrame(MZ_TIMER_RAF);
  MZ_TIMER_RAF = null;
}

function mzAttachKeys() {
  mzDetachKeys();
  MZ_KEY_HANDLER = function (e) {
    var dirMap = { ArrowUp: 'top', ArrowDown: 'bottom', ArrowLeft: 'left', ArrowRight: 'right' };
    var dir = dirMap[e.key];
    if (!dir) return;
    e.preventDefault();
    mzMove(dir);
  };
  document.addEventListener('keydown', MZ_KEY_HANDLER);
}
function mzDetachKeys() {
  if (MZ_KEY_HANDLER) document.removeEventListener('keydown', MZ_KEY_HANDLER);
  MZ_KEY_HANDLER = null;
}

function mzMove(dir) {
  if (MZ_INPUT_LOCKED || !MZ_MAZE) return;
  var cell = mzCellAt(MZ_PLAYER.x, MZ_PLAYER.y);
  if (cell[dir]) return; // 그 방향으로 벽이 있으면 못 감
  var deltas = { top: { x: 0, y: -1 }, bottom: { x: 0, y: 1 }, left: { x: -1, y: 0 }, right: { x: 1, y: 0 } };
  var d = deltas[dir];
  MZ_PLAYER = { x: MZ_PLAYER.x + d.x, y: MZ_PLAYER.y + d.y };
  /* 안개 효과 때문에 이동할 때마다 새로 밝혀지는 칸이 생길 수 있어서, 두 칸만 바꾸는 대신
     보드 전체를 다시 그립니다(미로 크기가 크지 않아 성능에는 문제없습니다). */
  mzRevealAround(MZ_PLAYER.x, MZ_PLAYER.y);
  mzRenderBoard();
  if (MZ_PLAYER.x === MZ_GOAL.x && MZ_PLAYER.y === MZ_GOAL.y) {
    mzFinishRound();
  }
}

function mzFinishRound() {
  MZ_INPUT_LOCKED = true;
  mzDetachKeys();
  mzStopTimerLoop();
  var elapsed = (performance.now() - MZ_ROUND_START_TIME) / 1000;
  MZ_ROUND_TIMES.push(elapsed);
  mzShowOnly('mz-clear-area');
  var isLast = MZ_ROUND_IDX + 1 >= MZ_TOTAL_ROUNDS;
  document.getElementById('mz-clear-msg').textContent = '🎉 ' + (MZ_ROUND_IDX + 1) + '번째 미로 클리어! (' + elapsed.toFixed(1) + '초)';
  document.getElementById('mz-next-btn').textContent = isLast ? '결과 보기' : '다음 미로';
}

function mzShowFinal() {
  mzShowOnly('mz-final-area');
  var total = MZ_ROUND_TIMES.reduce(function (a, b) { return a + b; }, 0);
  document.getElementById('mz-final-total').textContent = total.toFixed(1) + '초';
  if (MZ_BEST_TOTAL === null || total < MZ_BEST_TOTAL) {
    MZ_BEST_TOTAL = total;
    mzSaveBest(total);
  }
  document.getElementById('mz-final-best').textContent = mzBestText();
  mzPostResult(total);
}

/* ---- 온라인: 친구들 기록 표시 (10초 감각 게임과 같은 방식 - 각자 도전 후 기록 비교) ---- */
function mzResultKey(pid) { return roomKey('maze_r_' + pid); }

function mzPostResult(total) {
  if (playMode !== 'online' || !roomJoined || !myPlayerId) return;
  DBset(mzResultKey(myPlayerId), { name: me.name, total: total, ts: Date.now() });
}

function mzRenderOpponents() {
  var panel = document.getElementById('mz-opponents');
  if (!panel) return;
  if (playMode !== 'online' || !roomJoined || !roomPlayersList) { panel.innerHTML = ''; return; }
  Promise.all(roomPlayersList.map(function (p) {
    return DBget(mzResultKey(p.id)).then(function (data) { return { name: p.name, isMe: p.id === myPlayerId, data: data }; });
  })).then(function (results) {
    var entries = results.map(function (r) {
      var d = r.data;
      if (!d) return { name: r.name, isMe: r.isMe, label: '아직 도전 전', sortKey: [1, 0] };
      return { name: r.name, isMe: r.isMe, label: '총 ' + d.total.toFixed(1) + '초', sortKey: [0, d.total] };
    });
    entries.sort(function (a, b) { return a.sortKey[0] - b.sortKey[0] || a.sortKey[1] - b.sortKey[1]; });
    renderRankBoard('mz-opponents', entries);
  });
}

function mzStartOppPoll() {
  mzStopOppPoll();
  if (playMode !== 'online') return;
  mzRenderOpponents();
  MZ_OPP_POLL_TIMER = setInterval(mzRenderOpponents, 1500);
}
function mzStopOppPoll() {
  clearInterval(MZ_OPP_POLL_TIMER);
  MZ_OPP_POLL_TIMER = null;
}

function stopMaze() {
  mzStopTimerLoop();
  mzDetachKeys();
  mzStopOppPoll();
}
